var enSpecialClass = [
  {q:"By the time the committee finally reached a decision, the research team _______ on the project for over three years, and they _______ several major breakthroughs.",o:["had been working / had already achieved","was working / already achieved","has been working / has already achieved","worked / had already achieved"],a:0,e:"Past perfect continuous + past perfect",p:"Grammar"},
  {q:"If she _______ the supervisor's advice more seriously during the initial phase, she _______ so many difficulties in the final stages of the experiment.",o:["took / would not encounter","had taken / would not have encountered","has taken / will not encounter","would take / had not encountered"],a:1,e:"Third conditional (past unreal)",p:"Grammar"},
  {q:"Under no circumstances _______ the confidential documents to any unauthorized personnel, regardless of their position within the company.",o:["you should disclose","should you disclose","you disclose should","disclose you should"],a:1,e:"Inversion after negative adverbial",p:"Grammar"},
  {q:"The board of directors insisted that the new CEO _______ a comprehensive restructuring plan before the end of the fiscal quarter.",o:["presents","presented","present","will present"],a:2,e:"Subjunctive base form after 'insisted that'",p:"Grammar"},
  {q:"The renowned scientist _______ to have discovered a revolutionary method of carbon capture, although the findings have not yet been peer-reviewed.",o:["is believed","believes","is believing","has believed"],a:0,e:"Passive: 'is believed to have'",p:"Grammar"},
  {q:"_______ the arduous journey through the mountains, the expedition team finally reached the remote village, only to find it completely abandoned.",o:["Having completed","Completed","To complete","Completing"],a:0,e:"Perfect participle (having + past participle)",p:"Grammar"},
  {q:"The professor recommended that the student _______ the literature review before conducting the experiment, but the student decided to proceed without it.",o:["revises","revise","revised","will revise"],a:1,e:"Subjunctive base form after 'recommended that'",p:"Grammar"},
  {q:"The company _______ its employees _______ the new software by the end of the month, or the project timeline will be severely compromised.",o:["has / to be trained on","is having / train on","will have / trained on","had / to train on"],a:2,e:"Future perfect causative: 'will have + trained on'",p:"Grammar"},
  {q:"A: \"I'm afraid I can't accept your proposal in its current form. The budget estimates seem rather optimistic.\" B: \"_______ Perhaps we could revisit the figures together and find a more realistic middle ground?\"",o:["That's completely out of the question.","I see your point, but I think you're being overly cautious.","I appreciate your feedback, and I'd be happy to revise them.","You're absolutely right, and I have no intention of changing it."],a:2,e:"Accepting feedback and offering to revise",p:"Conversation"},
  {q:"A: \"Would you mind if I postponed our meeting until Thursday afternoon?\" B: \"_______ I have another engagement at that time, but Friday morning would work perfectly.\"",o:["Not at all.","I'd rather you didn't.","That sounds like a great idea.","I'm afraid that won't be possible."],a:1,e:"Polite refusal: 'I'd rather you didn't'",p:"Conversation"},
  {q:"A: \"From my perspective, the new policy will ultimately benefit the majority of employees.\" B: \"_______ I agree up to a point, but I think the implementation timeline is far too aggressive.\"",o:["That's exactly what I think.","I couldn't agree more.","I see what you mean, but I have some reservations.","You're completely wrong about that."],a:2,e:"Partial agreement with reservations",p:"Conversation"},
  {q:"A: \"The results of the experiment were inconclusive, to say the least.\" B: \"_______ In other words, we need to redesign the entire methodology.\"",o:["That's putting it mildly.","I don't follow you at all.","That's not what I meant.","You're missing the point entirely."],a:0,e:"Agreeing with an understatement",p:"Conversation"},
  {q:"A: \"I was wondering if you could possibly give me an extension on the deadline?\" B: \"_______ How much extra time do you think you'll need?\"",o:["I'm afraid that's not quite right.","I suppose that could be arranged.","That's totally out of the question.","I'd rather you didn't ask."],a:1,e:"Agreeing to a request",p:"Conversation"},
  {q:"A: \"So, to put it simply, the project failed because of poor communication between departments.\" B: \"_______ I think the root cause was actually a lack of clear leadership.\"",o:["That's partially true, however...","I couldn't have said it better.","That's exactly what I was going to say.","You've hit the nail on the head."],a:0,e:"Partial agreement then disagreement",p:"Conversation"},
  {q:"The findings of the study were considered _______ because the sample size was too small to draw any definitive conclusions.",o:["plausible","ambiguous","comprehensive","unprecedented"],a:1,e:"ambiguous = unclear / open to interpretation",p:"Vocabulary"},
  {q:"The government's decision to _______ the outdated subsidy program was met with widespread criticism from the agricultural sector.",o:["phase out","carry out","bring about","account for"],a:0,e:"phase out = gradually discontinue",p:"Vocabulary"},
  {q:"The relationship between economic growth and environmental degradation is often described as a _______, as pursuing one frequently comes at the expense of the other.",o:["tip of the iceberg","double-edged sword","burning the candle at both ends","blessing in disguise"],a:1,e:"double-edged sword = has benefits and drawbacks",p:"Vocabulary"},
  {q:"The CEO's resignation had a _______ effect on the company's stock price, causing it to plummet by nearly 20% within a single day.",o:["conductive","profound","controversial","feasible"],a:1,e:"profound = very great / deep",p:"Vocabulary"},
  {q:"The scientist's hypothesis was initially dismissed as _______, but subsequent experiments proved it to be entirely correct.",o:["plausible","substantial","implausible","comprehensive"],a:2,e:"implausible = not believable",p:"Vocabulary"},
  {q:"The new regulations are intended to _______ the gap between the wealthy and the disadvantaged in terms of access to higher education.",o:["deteriorate","bridge","pose","stem"],a:1,e:"bridge the gap = reduce the difference",p:"Vocabulary"},
  {q:"Identify the error: \"The professor, along with his research assistants, (A) have been working (B) diligently on the project (C) for the past eighteen months (D).\"",o:["have been working","diligently","for the past eighteen months","No error"],a:0,e:"'have been' should be 'has been' (agrees with 'The professor')",p:"Error Identification"},
  {q:"Identify the error: \"The new policy requires that each employee (A) submit their reports (B) not only on time but also (C) with complete accuracy and (D) professionally formatted.\"",o:["submit their reports","not only on time but also","with complete accuracy","professionally formatted"],a:3,e:"Parallelism: 'professionally formatted' lacks 'with'",p:"Error Identification"},
  {q:"Identify the error: \"(A) Having finished the experiment, (B) the results were analyzed (C) by the research team (D) with great care.\"",o:["Having finished the experiment","the results were analyzed","by the research team","with great care"],a:1,e:"Dangling modifier: 'Having finished' should modify the team",p:"Error Identification"},
  {q:"Identify the error: \"The committee decided to (A) repeat again the entire procedure (B) because the initial results were (C) not sufficiently reliable (D) to draw any conclusions.\"",o:["repeat again the entire procedure","because the initial results were","not sufficiently reliable","to draw any conclusions"],a:0,e:"Redundancy: 'repeat again'",p:"Error Identification"},
  {q:"The rapid advancement of artificial intelligence has sparked intense debate. (25)_______, the technology promises unprecedented efficiency and innovation across various sectors.",o:["Nevertheless","On the contrary","Admittedly","Consequently"],a:2,e:"Admittedly = conceding a point",p:"Cloze Test"},
  {q:"... (26)_______, concerns about job displacement, privacy violations, and algorithmic bias have grown increasingly vocal.",o:["Furthermore","However","Therefore","Similarly"],a:1,e:"However = contrast",p:"Cloze Test"},
  {q:"Many experts argue that without proper regulation, the risks (27)_______ the potential benefits.",o:["outweigh","undermine","deteriorate","stem from"],a:0,e:"outweigh = exceed in importance",p:"Cloze Test"},
  {q:"(28)_______, governments worldwide are now grappling with how to foster innovation while safeguarding public interests.",o:["As a result","For instance","In contrast","By comparison"],a:0,e:"As a result = consequence",p:"Cloze Test"},
  {q:"What is the main purpose of the passage on 'deep work'?",o:["To argue that deep work is the only path to success.","To present and critique the concept of deep work.","To explain why shallow work is more valuable than deep work.","To provide a biography of Cal Newport."],a:1,e:"Presents then critiques deep work",p:"Reading"},
  {q:"The word \"cultivate\" in the first paragraph is closest in meaning to:",o:["abandon","develop","ignore","criticize"],a:1,e:"cultivate = develop",p:"Reading"},
  {q:"According to the critics, one limitation of Newport's framework is that:",o:["it fails to acknowledge the value of collaborative and creative work.","it overemphasizes the role of technology in the workplace.","it ignores the importance of shallow work entirely.","it is based on outdated economic theories."],a:0,e:"Critics note collaborative/creative work is devalued",p:"Reading"},
  {q:"What can be inferred about the author's attitude toward Newport's concept?",o:["Completely dismissive","Enthusiastically supportive","Balanced and analytical","Indifferent and detached"],a:2,e:"Balanced and analytical",p:"Reading"},
  {q:"Which of the following is NOT a factor contributing to antibiotic resistance?",o:["Overprescription of antibiotics","Use of antibiotics in livestock","Patients not completing their prescribed courses","The discovery of penicillin by Alexander Fleming"],a:3,e:"The discovery itself is not a cause of resistance",p:"Reading"},
  {q:"What does the author mean by \"indiscriminate use\" in the first paragraph?",o:["Careful and targeted use","Random and unselective use","Illegal and underground use","Limited and controlled use"],a:1,e:"indiscriminate = random / unselective",p:"Reading"},
  {q:"Why does the author mention \"routine surgeries\" in the final paragraph?",o:["To argue that surgeries should be banned.","To illustrate the potential consequences of losing effective antibiotics.","To show that surgeries are the primary cause of resistance.","To emphasize that antibiotics are no longer useful."],a:1,e:"Illustrates consequences of losing antibiotics",p:"Reading"},
  {q:"Which of the following best describes the tone of the passage on antibiotics?",o:["Optimistic and celebratory","Cautionary and informative","Humorous and satirical","Neutral and indifferent"],a:1,e:"Cautionary and informative",p:"Reading"},
  {q:"What is the professor's main concern about the student's proposal?",o:["The research topic is too broad.","The methodology is flawed.","The timeline is unrealistic.","The literature review is insufficient."],a:2,e:"The timeline is unrealistic",p:"Listening",l:"Conversation: student and professor about the research proposal"},
  {q:"What does the professor suggest the student do?",o:["Change the research topic entirely.","Narrow the scope and resubmit the proposal.","Conduct a pilot study first.","Consult with another professor."],a:1,e:"Narrow the scope and resubmit",p:"Listening",l:"Conversation: student and professor about the research proposal"},
  {q:"According to the lecture, what is the primary cause of coral bleaching?",o:["Increased ocean acidity","Rising ocean temperatures","Overfishing","Pollution from plastics"],a:1,e:"Rising ocean temperatures",p:"Listening",l:"Lecture: impact of climate change on marine ecosystems"},
  {q:"What does the lecturer imply about the future of coral reefs?",o:["They will recover naturally within a decade.","They face irreversible damage without immediate action.","They are not significantly affected by climate change.","They will adapt to warmer temperatures over time."],a:1,e:"Irreversible damage without immediate action",p:"Listening",l:"Lecture: impact of climate change on marine ecosystems"}
];
