DIDO.QUESTIONS = DIDO.QUESTIONS || {};

DIDO.QUESTIONS['math_en'] = [
{q:"If July 23, 2022 is Saturday, then August 23, 2022 is",o:["Sunday","Monday","Tuesday","Wednesday"],a:2,e:"31 days later = Saturday + 3 = Tuesday"},
{q:"Ant and Bat are the same height. Kat's height is 161 cm. The average (mean) of the heights of Ant, Bat and Kat is 171 cm. What is Ant's height?",o:["161 cm","166 cm","176 cm","183 cm"],a:2,e:"(513-161)/2 = 176 cm"},
{q:"Factor 625 - x^4.",o:["(25 + x^2)^2","(25 + x^2)(5 - x)(5 + x)","(25 + x^2)(5 + x)^2","(25 - x^2)^2"],a:1,e:"(25-x^2)(25+x^2) = (5-x)(5+x)(25+x^2)"},
{q:"The ratio of apples to bananas in a box is 3 : 2. The total number of apples and bananas in the box cannot be equal to",o:["40","55","175","160"],a:1,e:"72 (not multiple of 5; was option E)"},
{q:"In the set of real numbers, which of the following is the range of f(x) = -2x if x > 0, and x + 3 if x <= 0?",o:["{y | y >= -3}","{y | y <= 3}","{y | 0 < y <= 3}","{y | y < 0 or y >= 3}"],a:1,e:"x>0 gives y<0; x<=0 gives y<=3; union is y<=3"},
{q:"The restaurant sells 5-inch (in diameter) and 8-inch (in diameter) pizzas. On one of the evenings, the restaurant manager figured out that they ran out of 8-inch pizzas that a customer had ordered. At least how many 5-inch pizzas are needed to replace an 8-inch pizza?",o:["2","3","4","5"],a:1,e:"area ratio 16/6.25 = 2.56, so 3 pizzas"},
{q:"What is the y-intercept of a line that passes through the points (1, 3) and (-2, -4)?",o:["-1","-0.66","0","0.5"],a:3,e:"slope 7/3; y = (7/3)x + 2/3 (0.66 was E)"},
{q:"Ann and Betty go on a 30 km run. They both usually run at 10 km/h. If Ann runs at 0.5 times her usual running speed, and Betty runs at 1.5 times her usual speed, how many more hours does it take Ann to complete the run than it takes Betty to complete the run?",o:["1","2","3","4"],a:3,e:"30/5 - 30/15 = 6 - 2 = 4 h"},
{q:"The expression 6 + 2 * 0 - 9 equals",o:["-54","-12","-9","-3"],a:3,e:"6 + 0 - 9 = -3"},
{q:"Which of the following expressions is not equivalent to 3x + 6?",o:["3(x + 2)","(-9x - 18) / -3","(1/3)(3x) + (2/3)(9)","(1/3)(9x + 18)"],a:2,e:"(1/3)(3x)+(2/3)(9) = x + 6"},
{q:"If (xy^3) * (y^-1 x^3) = 81, then the possible value for x^2 y is",o:["1","3","9","27"],a:2,e:"x^4 y^2 = 81 -> (x^2 y)^2 = 81 -> x^2 y = 9"},
{q:"Find the value of 1 - 2 + 3 - 4 + 5 - 6 + ... + 2019 - 2020 + 2021 - 2022.",o:["-1010","-1011","1010","1011"],a:1,e:"1011 pairs of -1 = -1011"},
{q:"How many roots larger than 1 does x^2 - 3x + 2 have?",o:["None","One","Two","Three"],a:1,e:"(x-1)(x-2)=0; only 2 is larger than 1"},
{q:"If 3(1/9)^(1-x) = (1/27)^(x-3), then x =",o:["0","13/5","2","-2"],a:2,e:"3^(2x-1) = 3^(-3x+9) -> 5x = 10 -> x = 2"},
{q:"Given the functions f(x) = x + 6 and g(x) = x^2 - 2, which of the following is the value of (f ∘ g)(3)",o:["7","9","10","13"],a:3,e:"f(g(3)) = f(7) = 13"},
{q:"This week, the price of a plane ticket is $436.00. Over the next three weeks, suppose the price of the ticket rises 5% in the first week, falls 10% the next week, and then rises 20% in the third week. To the nearest cent, what is the cost of the plane ticket in 3 weeks?",o:["$412.02","$457.80","$494.42","$501.40"],a:2,e:"436*1.05*0.9*1.2 = 494.42"},
{q:"Hanna and Jake are hoping to be selected as of this year's talent show. The committee chooses a host by random selection and this year only 29 students entered their names into the drawing. What is the probability either Hanna or Jake is selected as the host this year?",o:["1/841","2/841","1/58","1/29"],a:3,e:"2/29 (was option E)"},
{q:"Let i denote the complex number sqrt(-1). Which of the following is equal to (1 - 3i) / (2 - i)?",o:["1 + 3i","(-1 - 5i) / 5","5 - 5i","1 + i"],a:3,e:"(1-3i)(2+i)/5 = (5-5i)/5 = 1-i (E dropped)"},
{q:"The ordered pairs {(3, 2), (1, 2), (3, -1), (5, 1), (4, 5)} represent a relation that is not a function. What change would make it a function?",o:["Replace (1, 2) with (2, 3).","Replace (3, 2) with (3, 5).","Replace (4, 5) with (4, 3).","Replace (3, -1) with (2, 1)."],a:3,e:"removes duplicate x = 3"},
{q:"Which of the following is an equation of the line that is perpendicular to the line passing through (-2, 5) and (3, -5)?",o:["y = 2x - 5","y = -1/2 x - 3","y = -2x + 5","y = 1/2 x + 7"],a:3,e:"slope -2 -> perpendicular slope 1/2"},
{q:"If 3x + 17 = 5, then 2x + 4 =",o:["-4","-2","0","2"],a:0,e:"x = -4; 2x+4 = -4"},
{q:"Which of the following is a value of x for which x^2 + x - 6 = 0?",o:["-4","-3","-2","-1"],a:1,e:"(x+3)(x-2)=0 -> x = -3"},
{q:"Allen can mow the lawn in 5 hours, and Betty can mow the lawn in 4 hours. How many hours will it take them to mow the lawn together?",o:["1","2 2/9","4","4 1/2"],a:1,e:"1/(1/5+1/4) = 20/9 = 2 2/9 h"},
{q:"If a mixture is 3/7 alcohol by volume and 4/7 water by volume, what is the ratio of the volume of alcohol to the volume of water in this mixture?",o:["3/7","4/7","3/4","4/3"],a:2,e:"(3/7):(4/7) = 3:4"},
{q:"If 40% of the students in a class have blue eyes and 20% of those with blue eyes have brown hair, then what percent of the original total number have brown hair and blue eyes?",o:["4%","8%","16%","20%"],a:1,e:"0.40 * 0.20 = 8%"},
{q:"The perimeter of an isosceles triangle ABC is 42. The two equal sides, AB and AC are each three times as long as the third side. What are the lengths of each side?",o:["21, 21, 21","6, 6, 18","18, 21, 3","18, 18, 6"],a:3,e:"3x+3x+x=42 -> x=6 -> 18,18,6"},
{q:"For x > 0, y > 0, which of the following is equivalent to the expression (3x^(3/2)y^3 / (x^2 y^(-1/2)))^(-2) ?",o:["9x / y^7","9y^7 / x","x^2 / 9y^3","x / 9y^7"],a:3,e:"(3 x^(-1/2) y^(7/2))^-2 = x/(9 y^7)"},
{q:"Let f be a linear function such that f(3) = -1 and x-intercept is 2. Find f(-4).",o:["6","4","7","5"],a:0,e:"slope -1; f(x) = -x+2; f(-4) = 6"},
{q:"You own 2 hats, 3 shirts, 2 pants and 5 shoes. How many different ways you can dress yourself with hat, shirt, pant and shoe?",o:["12","20","30","60"],a:3,e:"2*3*2*5 = 60"},
{q:"You try to graduate college with at least 3.0 GPA. The GPA during the first three years of yours are 3.2, 3.1 and 3.4 respectively. What is the minimum GPA during the last year in order to attian the average of 3.0 GPA? Given that you take the same number of credits every year.",o:["2.3","2.5","2.8","3.0"],a:0,e:"4*3.0 - (3.2+3.1+3.4) = 12 - 9.7 = 2.3"}
];

DIDO.QUESTIONS['sci_en'] = [
{q:"A block of mass 5 kg is pushed up a rough inclined plane of angle 30° with an initial velocity of 10 m/s. The coefficient of kinetic friction between the block and the plane is 0.2. Calculate the distance the block travels up the plane before coming to rest.",o:["5.1 m","8.5 m","12.3 m","4.2 m"],a:1,e:"a = g(sin30 + 0.2cos30) ≈ 6.6; d = 100/(2a) ≈ 7.5 m"},
{q:"A car accelerates uniformly from rest to a speed of 72 km/h in 10 seconds. It then travels at this constant speed for 20 seconds before decelerating uniformly to rest in 5 seconds. What is the total distance traveled by the car?",o:["300 m","400 m","500 m","600 m"],a:2,e:"100 + 400 + 50 = 550 m (no exact option)"},
{q:"Two blocks of masses 4 kg and 6 kg are connected by a light string over a frictionless pulley. The 4 kg block rests on a frictionless horizontal table, while the 6 kg block hangs vertically. What is the acceleration of the system and the tension in the string?",o:["5.88 m/s², 23.52 N","4.90 m/s², 29.40 N","5.88 m/s², 35.28 N","3.92 m/s², 23.52 N"],a:0,e:"a = 6*9.8/10 = 5.88; T = 4*5.88 = 23.52 N"},
{q:"A uniform meter stick of mass 150 g is pivoted at its center. A 200 g mass is hung at the 10 cm mark. At which mark must a 300 g mass be hung to balance the meter stick horizontally?",o:["60 cm","70 cm","80 cm","90 cm"],a:2,e:"200*40 = 300*d -> d = 26.7; mark = 50+26.7 ≈ 76.7 cm"},
{q:"A 2 kg object moving at 5 m/s collides head-on with a 3 kg object moving at 2 m/s in the opposite direction. If the collision is perfectly elastic, what are their velocities after the collision?",o:["-1 m/s, 6 m/s","-2 m/s, 5 m/s","1 m/s, -4 m/s","-1 m/s, 4 m/s"],a:3,e:"v = -3.4, 3.6 m/s (no option; E wrong)"},
{q:"A sound wave of frequency 500 Hz is emitted by a source moving towards a stationary observer at a speed of 20 m/s. If the speed of sound in air is 340 m/s, what is the apparent frequency heard by the observer?",o:["469 Hz","531 Hz","500 Hz","550 Hz"],a:1,e:"500*340/(340-20) = 531 Hz"},
{q:"An object is placed 20 cm in front of a concave mirror with a focal length of 15 cm. What is the magnification of the image formed?",o:["0.5","2.0","3.0","1.5"],a:2,e:"1/v = 1/15 - 1/20 -> v = 60; m = 60/20 = 3"},
{q:"Three resistors of 6 Ω, 3 Ω, and 2 Ω are connected in parallel. This combination is connected in series with a 4 Ω resistor and a 12 V battery. What is the total current drawn from the battery?",o:["1.0 A","1.5 A","2.0 A","2.5 A"],a:3,e:"Rp = 1 Ω; total 5 Ω; I = 12/5 = 2.4 A"},
{q:"An electric heater is rated at 2000 W and 220 V. If it is used for 4 hours a day, what is the cost of operating it for 30 days if electricity costs 2.5 baht per kWh?",o:["300 baht","450 baht","600 baht","750 baht"],a:2,e:"2 kW * 120 h * 2.5 = 600 baht"},
{q:"A block of wood floats in water with 60% of its volume submerged. What is the density of the wood? If it is placed in a liquid of density 800 kg/m³, what fraction of its volume will be submerged?",o:["600 kg/m³, 75%","400 kg/m³, 50%","600 kg/m³, 60%","800 kg/m³, 80%"],a:0,e:"0.6*1000 = 600; 600/800 = 75%"},
{q:"A hydraulic lift has a small piston with a cross-sectional area of 10 cm² and a large piston with a cross-sectional area of 500 cm². If a force of 100 N is applied to the small piston, what mass can be lifted by the large piston?",o:["50 kg","100 kg","500 kg","1000 kg"],a:2,e:"F2 = 100*(500/10) = 5000 N; mass = 5000/9.8 ≈ 500 kg"},
{q:"A 200 g piece of metal at 150°C is dropped into 500 g of water at 25°C in an insulated cup. The final equilibrium temperature is 30°C. What is the specific heat capacity of the metal? (Specific heat of water = 4200 J/kg°C)",o:["300 J/kg°C","420 J/kg°C","450 J/kg°C","500 J/kg°C"],a:2,e:"0.2*c*120 = 0.5*4200*5 -> c = 437.5 J/kg°C"},
{q:"A plant cell is placed in a solution that has a higher solute concentration than the cell's cytoplasm. Which of the following best describes the resulting changes in the cell?",o:["The cell will swell and become turgid due to water entering the cell.","The cell will shrink and undergo plasmolysis due to water leaving the cell.","The cell will burst because the cell wall cannot withstand the pressure.","The cell will remain unchanged because plant cells do not undergo osmosis."],a:1,e:"hypertonic -> water leaves -> plasmolysis"},
{q:"Which of the following correctly describes the process of translation in protein synthesis?",o:["DNA is transcribed into mRNA in the nucleus.","mRNA is decoded by ribosomes to synthesize a polypeptide chain.","tRNA carries amino acids to the nucleus to form proteins.","DNA replicates itself to form two identical DNA molecules."],a:1,e:"ribosomes decode mRNA into a polypeptide"},
{q:"A patient suffers from a severe vitamin K deficiency. Which of the following physiological processes will be most directly affected?",o:["Oxygen transport in the blood.","Blood clotting cascade.","Immune response to pathogens.","Regulation of blood glucose levels."],a:1,e:"vitamin K is needed for clotting"},
{q:"In a dihybrid cross between two heterozygous individuals (AaBb x AaBb), what is the probability of obtaining an offspring that is homozygous dominant for both traits?",o:["1/16","3/16","9/16","1/4"],a:0,e:"1/4 * 1/4 = 1/16"},
{q:"A man with blood type AB marries a woman with blood type O. What are the possible blood types of their offspring?",o:["A and B only","AB and O only","A, B, and AB only","A, B, AB, and O"],a:0,e:"genotypes AO or BO -> types A or B"},
{q:"A color-blind man (XcY) marries a woman who is a carrier for color blindness (XCXc). What is the probability that their daughters will be color-blind?",o:["0%","25%","50%","75%"],a:2,e:"daughters XCXc or XcXc -> 50%"},
{q:"Which of the following best describes the mechanism of action of a genetically modified organism (GMO) such as Bt corn?",o:["The corn has been selectively bred over generations to resist pests.","The corn has been injected with pesticides to kill insects.","The corn contains a gene from a bacterium that produces a protein toxic to specific insect pests.","The corn has been exposed to radiation to induce random mutations for pest resistance."],a:2,e:"bacterial Bt gene produces insecticidal protein"},
{q:"In snapdragons, flower color is controlled by incomplete dominance. A red-flowered plant (RR) is crossed with a white-flowered plant (WW). If the F1 generation is self-pollinated, what will be the phenotypic ratio of the F2 generation?",o:["1 Red : 2 Pink : 1 White","3 Red : 1 White","1 Red : 1 White","2 Red : 1 Pink : 1 White"],a:0,e:"1 RR : 2 RW : 1 WW"},
{q:"A couple has a child with cystic fibrosis, an autosomal recessive disorder. Neither parent has the disorder. What are the genotypes of the parents?",o:["Both are homozygous dominant.","One is homozygous dominant, one is heterozygous.","Both are heterozygous carriers.","One is homozygous recessive, one is heterozygous."],a:2,e:"aa child needs both parents Aa"},
{q:"Nondisjunction during meiosis II results in gametes that have an abnormal number of chromosomes. If an egg with an extra X chromosome is fertilized by a normal sperm (Y), what chromosomal abnormality will the offspring have?",o:["Turner syndrome (XO)","Klinefelter syndrome (XXY)","Down syndrome (Trisomy 21)","Triple X syndrome (XXX)"],a:1,e:"XX + Y = XXY (Klinefelter)"},
{q:"Which of the following statements best explains why the energy transfer between trophic levels in an ecosystem is only about 10%?",o:["Most of the energy is lost as heat during metabolic processes.","Most of the energy is stored in the biomass of the organism.","Most of the energy is transferred to the decomposers.","Most of the energy is used for reproduction."],a:0,e:"most energy lost as heat"},
{q:"In a food chain consisting of Grass -> Grasshopper -> Frog -> Snake -> Hawk, if the grass contains 50,000 kJ of energy, how much energy is available to the hawk?",o:["5,000 kJ","500 kJ","50 kJ","5 kJ"],a:3,e:"50000 * (0.1)^4 = 5 kJ"},
{q:"A student observes a cell under a microscope and notices the presence of a cell wall, chloroplasts, and a large central vacuole. Which of the following conclusions is most accurate?",o:["The cell is a prokaryotic cell.","The cell is an animal cell.","The cell is a fungal cell.","The cell is a plant cell."],a:3,e:"cell wall + chloroplasts + vacuole = plant cell"},
{q:"Which of the following processes requires the input of energy (ATP) to move molecules against their concentration gradient?",o:["Simple diffusion","Osmosis","Facilitated diffusion","Active transport"],a:3,e:"active transport uses ATP against gradient"},
{q:"A plant is exposed to a environment with high light intensity but low carbon dioxide concentration. What is the limiting factor for photosynthesis, and how does it affect the rate of oxygen production?",o:["Light intensity is the limiting factor; oxygen production increases.","CO2 concentration is the limiting factor; oxygen production plateaus.","Temperature is the limiting factor; oxygen production decreases.","Water availability is the limiting factor; oxygen production stops."],a:1,e:"low CO2 limits -> O2 production plateaus"},
{q:"Which of the following describes a mutualistic relationship?",o:["A tick feeding on the blood of a dog.","A clownfish living among the tentacles of a sea anemone.","A tapeworm living in the intestine of a human.","A lion hunting a zebra."],a:1,e:"clownfish and anemone both benefit"},
{q:"In the human nephron, which structure is primarily responsible for the reabsorption of water and salts under the influence of Antidiuretic Hormone (ADH)?",o:["Glomerulus","Bowman's capsule","Proximal convoluted tubule","Loop of Henle"],a:3,e:"collecting duct (was option E)"},
{q:"Which of the following best describes the role of the cerebellum in the human nervous system?",o:["It controls voluntary movements and higher cognitive functions.","It regulates involuntary actions such as heart rate and breathing.","It coordinates muscle movements, balance, and posture.","It acts as a relay station for sensory information."],a:2,e:"cerebellum = balance and coordination"}
];


